def test_campaign_summary_basic():
    e = [{"id": "a", "day": 1, "converted": True}, {"id": "b", "day": 2, "converted": False}]
    assert campaign_summary({"g": e}, 1)["groups"] == 1


def test_conversion_rate_none_counts_as_not_converted():
    assert conversion_rate(
        [{"converted": True}, {"converted": None}, {"converted": False}]
    ) == pytest.approx(1 / 3)
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_each_session_once():
    groups = {
        "large": [{"converted": True}] + [{"converted": False}] * 9,
        "small": [{"converted": True}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == pytest.approx(2 / 11)
    assert pooled_conversion_rate({"empty": []}) == 0.0


def test_conversions_in_window_uses_exactly_last_days():
    assert conversions_in_window([1, 2, 3, 4], 2) == 7
    assert conversions_in_window([1, 2], 5) == 3
    assert conversions_in_window([1, 2], 0) == 0


def test_parse_session_log_fields_and_skipped_lines():
    assert parse_session_log(
        ["  # note", "", " x1 , 3 , 1 ", "x2,4,0", "x3,5,"]
    ) == [
        {"id": "x1", "day": 3, "converted": True},
        {"id": "x2", "day": 4, "converted": False},
        {"id": "x3", "day": 5, "converted": None},
    ]


@pytest.mark.parametrize("line", ["x,not-a-day,1", "x,1", "x,1,1,extra"])
def test_parse_session_log_errors_include_input_line_number(line):
    with pytest.raises(ValueError, match="line 2"):
        parse_session_log(["# skipped", line])


def test_dedupe_sessions_keeps_last_duplicate_id():
    events = [
        {"id": "x", "day": 1, "converted": True},
        {"id": "y", "day": 2, "converted": False},
        {"id": "x", "day": 3, "converted": False},
    ]
    assert dedupe_sessions(events) == [events[1], events[2]]


def test_daily_conversion_counts_is_inclusive_and_fills_gaps():
    events = [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 3, "converted": True},
        {"id": "c", "day": 3, "converted": False},
        {"id": "d", "day": 5, "converted": True},
    ]
    assert daily_conversion_counts(events, 2, 4) == [0, 1, 0]
    assert daily_conversion_counts(events, 4, 2) == []


def test_campaign_summary_rounding_recent_and_active_groups():
    groups = {
        "active": [
            {"id": "a", "day": 1, "converted": True},
            {"id": "b", "day": 2, "converted": False},
            {"id": "c", "day": 3, "converted": True},
        ],
        "empty": [],
    }
    assert campaign_summary(groups, 1) == {"rate": 0.667, "recent": 1, "groups": 1}
    assert campaign_summary({}, 7) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"converted": True}],
        "a": [{"converted": True}],
        "empty": [],
        "middle": [{"converted": True}, {"converted": False}],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]


def test_conversion_rate_by_group_sorted_and_empty_is_none():
    assert conversion_rate_by_group(
        {"z": [], "b": [{"converted": False}], "a": [{"converted": True}]}
    ) == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_conversion_streak_requires_positive_counts():
    assert longest_conversion_streak([1, 2, 0, -1, 3]) == 2
    assert longest_conversion_streak([]) == 0
